#!/usr/bin/env python3
"""Read-only API payload and mobile WebUI for the operations queue."""
from __future__ import annotations

import json
import sqlite3
from pathlib import Path
from typing import Any

from agent_queue_store_v1093 import DEFAULT_DB, read_snapshot


QUEUE_DB = DEFAULT_DB


def api_payload(db_path: Path = QUEUE_DB) -> dict[str, Any]:
    try:
        payload = read_snapshot(db_path)
        payload["ok"] = True
        payload["source"] = "operations-db"
        payload["database"] = str(db_path)
        return payload
    except (OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as error:
        return {
            "ok": False,
            "schema": "agent-queue-error-v1093",
            "source": "operations-db",
            "database": str(db_path),
            "error": f"{type(error).__name__}: {error}",
        }


